# Calcula transporte ida y vuelta via Nominatim + OSRM
TARIFA = float(env['ir.config_parameter'].sudo().get_param('atheron.transporte_tarifa_km', '1600') or 1600)
PRODUCTO_ID = 12229

CIUDADES = ['bogota', 'zipaquira', 'cajica', 'chia', 'cota', 'sopo', 'tocancipa', 'soacha', 'mosquera', 'funza', 'madrid']

def _norm(addr):
    a = ' ' + (addr or '').strip() + ' '
    a = a.replace('#', ' ').replace('  ', ' ')
    repl = [(' Cra ', ' Carrera '), (' Cra. ', ' Carrera '), (' Cr ', ' Carrera '), (' Cr. ', ' Carrera '), (' Kr ', ' Carrera '), (' Kra ', ' Carrera '), (' Cll ', ' Calle '), (' Cll. ', ' Calle '), (' Cl ', ' Calle '), (' Cl. ', ' Calle '), (' Av ', ' Avenida '), (' Av. ', ' Avenida '), (' Avda ', ' Avenida '), (' Avda. ', ' Avenida '), (' Dg ', ' Diagonal '), (' Dg. ', ' Diagonal '), (' Diag ', ' Diagonal '), (' Tv ', ' Transversal '), (' Tv. ', ' Transversal '), (' Trans ', ' Transversal '), (' Bgta ', ' Bogota '), (' Bta ', ' Bogota '), (' Zipa ', ' Zipaquira ')]
    al = a.lower()
    out = a
    for old, new in repl:
        if old.lower() in al:
            i = al.find(old.lower())
            while i >= 0:
                out = out[:i] + new + out[i+len(old):]
                al = out.lower()
                i = al.find(old.lower(), i+len(new))
    digits = '0123456789'
    res = []
    i = 0
    while i < len(out):
        c = out[i]
        if c == ' ' and i+2 < len(out) and out[i+1] == '-' and out[i+2] == ' ':
            if res and res[-1] in digits + 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ' and i+3 < len(out) and out[i+3] in digits:
                res.append('-')
                i += 3
                continue
        res.append(c)
        i += 1
    out = ''.join(res)
    while '  ' in out:
        out = out.replace('  ', ' ')
    return out.strip()

def _ciudad_en(addr):
    al = addr.lower()
    for c in CIUDADES:
        if c in al:
            return c.capitalize()
    return ''

def _strip_num_placa(addr):
    parts = addr.split(' ')
    out = []
    for p in parts:
        if '-' in p and any(ch.isdigit() for ch in p):
            a, _, b = p.partition('-')
            if a and b and len(a) <= 4 and len(b) <= 4 and any(ch.isdigit() for ch in a):
                continue
        out.append(p)
    return ' '.join(out)

def _geocode(addr):
    headers = {'User-Agent': 'Atheron-Odoo-Transport/1.0', 'Accept-Language': 'es'}
    ciudad = _ciudad_en(addr)
    sin_placa = _strip_num_placa(addr)
    intentos = []
    intentos.append(addr + ', Colombia')
    if ciudad and ciudad.lower() not in addr.lower()[-30:]:
        intentos.append(addr + ', ' + ciudad + ', Colombia')
    if sin_placa and sin_placa != addr:
        intentos.append(sin_placa + ', Colombia')
        if ciudad:
            intentos.append(sin_placa + ', ' + ciudad + ', Colombia')
    if ciudad:
        intentos.append(ciudad + ', Colombia')
    seen = set()
    for q in intentos:
        if q in seen:
            continue
        seen.add(q)
        try:
            r = requests.get('https://nominatim.openstreetmap.org/search', params={'format': 'json', 'limit': 1, 'q': q, 'countrycodes': 'co'}, headers=headers, timeout=15)
            d = r.json()
            if d:
                return float(d[0]['lon']), float(d[0]['lat']), q, d[0].get('display_name', '')
        except Exception:
            pass
    return None

order_ids = env.context.get('active_ids') or []
if not order_ids and records:
    order_ids = records.ids
if not order_ids:
    raise UserError('No se detecto cotizacion activa.')

resumen = []
for order in env['sale.order'].browse(order_ids):
    origen_raw = (order.x_origen_transporte or '').strip()
    destino_raw = (order.x_destino_transporte or '').strip()
    if not destino_raw:
        destino_raw = ' '.join((order.partner_id.contact_address or '').split())
        if destino_raw:
            order.write({'x_destino_transporte': destino_raw})
    if not origen_raw:
        raise UserError('Debe escribir el ORIGEN del transporte.')
    if not destino_raw:
        raise UserError('No se encontro direccion del cliente. Escriba el DESTINO manualmente.')

    origen = _norm(origen_raw)
    destino = _norm(destino_raw)

    # Si origen empieza con "geo:lat,lon" parsea coords directas (capturado por GPS)
    g1 = None
    if origen_raw.lower().startswith('geo:'):
        try:
            coords = origen_raw[4:].split(' ')[0]
            lat_s, lon_s = coords.split(',')
            g1 = (float(lon_s), float(lat_s), 'GPS', 'GPS')
        except Exception:
            g1 = None
    if not g1:
        g1 = _geocode(origen)
    if not g1:
        raise UserError('No se pudo ubicar el ORIGEN.\nIngresado: ' + origen_raw + '\nNormalizado: ' + origen + '\n\nTip: usa "Carrera 9 10-32, Zipaquira" o "Calle 80 45-23, Bogota". No agregues "#" ni "No", deja el numero como "X-Y" pegado.')
    g2 = _geocode(destino)
    if not g2:
        raise UserError('No se pudo ubicar el DESTINO.\nIngresado: ' + destino_raw + '\nNormalizado: ' + destino)

    osrm = 'https://router.project-osrm.org/route/v1/driving/%f,%f;%f,%f' % (g1[0], g1[1], g2[0], g2[1])
    r3 = requests.get(osrm, params={'overview': 'false'}, timeout=15)
    rj = r3.json()
    if rj.get('code') != 'Ok' or not rj.get('routes'):
        raise UserError('OSRM no pudo calcular la ruta.')
    km_ida = round(rj['routes'][0]['distance'] / 1000.0, 1)
    if km_ida < 0.1:
        raise UserError('Distancia 0 km. Origen y destino quedaron en el mismo punto. Especifica mejor las direcciones.')
    km_total = round(km_ida * 2, 1)

    order.write({'x_km_transporte': km_ida})

    existing = order.order_line.filtered(lambda l: l.product_id.id == PRODUCTO_ID)
    if existing:
        existing[0].write({'product_uom_qty': km_total, 'price_unit': TARIFA})
    else:
        order.write({'order_line': [(0, 0, {'product_id': PRODUCTO_ID, 'product_uom_qty': km_total, 'price_unit': TARIFA})]})

    resumen.append('%s: %.1f km ida+vuelta = $%s' % (order.name, km_total, '{:,.0f}'.format(km_total * TARIFA)))

msg = ' | '.join(resumen) if resumen else 'Sin procesar'
action = {'type': 'ir.actions.client', 'tag': 'display_notification', 'params': {'title': 'Transporte calculado', 'message': msg, 'type': 'success', 'sticky': False, 'next': {'type': 'ir.actions.act_window_close'}}}

# ATHERON - Al cancelar la cotización: cancela y archiva las tareas FSM vinculadas
if record.state == 'cancel':
    tasks = env['project.task'].sudo().search([
        ('sale_order_id', '=', record.id),
        ('active', '=', True)
    ])
    if tasks:
        tasks.write({'state': '1_canceled', 'active': False})

PS = env['planning.slot'].sudo()
now = fields.Datetime.now()
dirty = []
for order in records:
    order.write({'x_checkin_done': True, 'x_checkin_actual': now})
    line_ids = order.order_line.ids
    if line_ids:
