            for rol in slots.mapped('role_id'):
                if rol.x_estado_limpieza == 'sucia' and rol.name not in dirty:
                    dirty.append(rol.name)
if dirty:
    action = {
        'type': 'ir.actions.client',
        'tag': 'display_notification',
        'params': {
            'title': 'Atencion: habitacion SUCIA',
            'message': 'Check-in realizado, pero esta(s) habitacion(es) figuran SUCIAS: ' + ', '.join(dirty) + '. Coordina la limpieza.',
            'type': 'warning',
            'sticky': True,
        },
    }

PS = env['planning.slot'].sudo()
now = fields.Datetime.now()
for order in records:
    order.write({'x_checkout_done': True, 'x_checkout_actual': now})
    line_ids = order.order_line.ids
    if line_ids:
        slots = PS.search([('sale_line_id', 'in', line_ids)])
        published = slots.filtered(lambda s: s.state == 'published')
        if published:
            published.write({'state': 'draft'})
        if slots:
            slots.write({'x_checkin_state': 'checked_out'})
            roles = slots.mapped('role_id')
            if roles:
                roles.write({'x_estado_limpieza': 'sucia'})

PS = env['planning.slot'].sudo()
for order in records:
    if not (order.x_checkin and order.x_checkout):
        continue
    ci = order.x_checkin
    co = order.x_checkout
    if co <= ci:
        continue
    st = ci.strftime('%Y-%m-%d') + ' 12:00:00'
