        role = line.product_id.product_tmpl_id.planning_role_id
        if not role:
            continue
        if any([s.start_datetime for s in line.planning_slot_ids]):
            continue
        rid = role.resource_ids[:1].id
        PS.create({'role_id': role.id, 'resource_id': rid, 'start_datetime': st, 'end_datetime': en, 'sale_line_id': line.id})

hotel_cats = env['product.category'].sudo().search([('id','child_of',[6,1247,1242,1296])]).ids
for order in records:
    if order.x_checkin and order.x_checkout:
        noches = (order.x_checkout - order.x_checkin).days
        if noches > 0:
            for line in order.order_line:
                if line.product_id and line.product_id.categ_id and line.product_id.categ_id.id in hotel_cats and line.x_noches != noches:
                    line.write({'x_noches': noches})

hotel_cats = env['product.category'].sudo().search([('id','child_of',[6,1247,1242,1296])]).ids
if record.x_checkin and record.x_checkout:
    noches = (record.x_checkout - record.x_checkin).days
    if noches > 0:
        for line in record.order_line:
            if line.product_id and line.product_id.categ_id and line.product_id.categ_id.id in hotel_cats and line.x_noches != noches:
                line.write({'x_noches': noches})

for so in records:
    if so.x_tecnico_id:
        tasks = env['project.task'].sudo().search([('sale_order_id', '=', so.id)])
        for t in tasks:
            if t.x_tecnico_id.id != so.x_tecnico_id.id:
