        if draft:
            draft.write({'state': 'published'})
        if slots:
            new_state = 'checked_in' if order.x_checkin_done else 'confirmed'
            slots.write({'x_checkin_state': new_state})

PS = env['planning.slot'].sudo()
for order in records:
    if not order.x_checkin or not order.x_checkout:
        continue
    ci = order.x_checkin
    co = order.x_checkout
    if co <= ci:
        continue
    st = datetime.datetime(ci.year, ci.month, ci.day, 20, 0, 0)
    en = datetime.datetime(co.year, co.month, co.day, 16, 0, 0)
    for line in order.order_line:
        for s in line.planning_slot_ids:
            if s.start_datetime and (s.start_datetime != st or s.end_datetime != en):
                s.write({'start_datetime': st, 'end_datetime': en})

if record.x_zipaquira:
    record.write({'warehouse_id': 6})
else:
