    for line in record.order_line:
        if line.product_id and line.product_id.is_storable:
            quant = env['stock.quant'].search([
                ('product_id', '=', line.product_id.id),
                ('location_id', '=', 74)
            ], limit=1)
            disponible = quant.quantity if quant else 0
