    raise UserError('TARIFA vigente: solo "%s" puede cambiar su estado.' % GROUP)
for r in records:
    if r.x_gov_state not in ('approved', 'published', 'synced', 'retired'):
        raise UserError('TARIFA %s: una versión vigente no puede volver a %s. Use RETIRED y cree nueva versión.' % (r.x_rule_code, (r.x_gov_state or 'draft').upper()))
    if r.x_gov_state == 'retired':
        r.sudo().write({'x_notes': (r.x_notes or '') + '\nRETIRED por %s el %s UTC' % (env.user.name, datetime.datetime.now())})

